const { chromium, devices } = require('playwright');
const note = (s) => console.log(`::notice::${s}`);
(async () => {
  await new Promise((r) => setTimeout(r, 10000));
  const b = await chromium.launch();
  const ctx = await b.newContext({ ...devices['iPhone 13'], locale: 'uz' });
  await ctx.addInitScript(() => { try { localStorage.setItem('mx_lang', 'uz'); if (!sessionStorage.getItem('x')) { localStorage.setItem('mx_country', 'TJ'); sessionStorage.setItem('x', '1'); } } catch {} });
  const p = await ctx.newPage();
  const errs = []; p.on('pageerror', (e) => errs.push(e.message));
  await p.goto('https://hemu.uz/transportsale', { waitUntil: 'load' }); await p.waitForTimeout(3000);
  const hint = await p.locator('[data-elsewhere]').innerText().catch(() => 'YOQ');
  note('tugma: ' + hint);
  await p.locator('[data-elsewhere]').scrollIntoViewIfNeeded().catch(() => {});
  await p.screenshot({ path: 'oldin.png' });
  await p.click('[data-elsewhere]').catch(() => {}); await p.waitForTimeout(2500);
  note('keyin: ' + await p.locator('.results-head h2').first().innerText().catch(() => '?'));
  await p.screenshot({ path: 'keyin.png' });
  note('xatolar: ' + (errs.join(' | ') || "yo'q"));
  await b.close();
})().catch((e) => { console.log(`::error::${e.message}`); process.exit(1); });
